<?php
declare(strict_types=1);
require_once __DIR__.'/../api/analytics_sync.php';
require_once __DIR__.'/fixtures/analytics/database.php';
function syncCheck(bool $v,string $label):void{if(!$v)throw new RuntimeException($label);}
$pdo=analyticsTestDatabase();$calls=0;
$disabled=syncAnalytics($pdo,'disabled',[],static function()use(&$calls){$calls++;throw new RuntimeException('disabled called network');});
syncCheck($calls===0&&$disabled['pages']===0,'disabled no network');
// Existing engine + authenticated export fixture generated by PostgreSQL test.
$path=getenv('ANALYTICS_ENGINE_EVENT_JSON');if(!$path)throw new RuntimeException('Run PostgreSQL delivery test first, provide fixture path');
$event=json_decode(file_get_contents($path),true,64,JSON_THROW_ON_ERROR);
$event['run']['id']='frozen-test-run';$event['run']['status']='SUCCEEDED';
$fail=true;
$transport=static function($method,$path,$body)use(&$calls,&$fail,$event){
    $calls++;
    if(str_contains($path,'/publications?'))return ['items'=>[['sequence'=>1,'run_id'=>'frozen-test-run']],'next_after'=>null];
    if($fail){$fail=false;throw new RuntimeException('Synthetic temporary API failure');}
    $invalid=$event;$invalid['score']='invalid';
    return ['run'=>$event['run'],'items'=>[$event,$invalid],'next_after'=>null];
};
try{syncAnalytics($pdo,'dry_run',[],$transport,1);throw new RuntimeException('Expected API failure');}catch(RuntimeException $e){if($e->getMessage()!=='Synthetic temporary API failure')throw $e;}
$state=$pdo->query('SELECT * FROM analytics_sync_state')->fetch(PDO::FETCH_ASSOC);
syncCheck($state['current_run_id']==='frozen-test-run'&&(int)$state['publication_sequence']===0,'failure keeps frozen cursor');
$result=syncAnalytics($pdo,'dry_run',[],$transport,1);
syncCheck($result['processed']===1&&$result['rejected']===1,'retry processes valid event and quarantines invalid event');
syncCheck((int)$pdo->query('SELECT COUNT(*) FROM analytics_delivery_rejections')->fetchColumn()===1,'permanent invalid event does not poison feed');
syncCheck((int)$pdo->query('SELECT COUNT(*) FROM manager_tasks')->fetchColumn()===0,'real SHADOW event never creates task');
syncCheck($pdo->query('SELECT decision FROM analytics_inbox')->fetchColumn()==='BLOCKED','shadow receipt blocked');
$state=$pdo->query('SELECT * FROM analytics_sync_state')->fetch(PDO::FETCH_ASSOC);
syncCheck((int)$state['publication_sequence']===1&&$state['current_run_id']===null,'cursor commits after receipt');
processAnalyticsEvent($pdo,$event,null,[],'enabled',time());
syncCheck((int)$pdo->query('SELECT COUNT(*) FROM manager_tasks')->fetchColumn()===0,'even enabled cannot promote SHADOW');
echo "analytics_sync_test: real engine SHADOW export + failure/retry/checkpoint + no promotion OK\n";
